-- VACUUM's options as ExecVacuum checks them. PROCESS_MAIN false leaves the
-- table unvacuumed, SKIP_LOCKED passes over a table another transaction
-- holds, ONLY_DATABASE_STATS vacuums no table; the others select nothing
-- this engine has and are checked only.
CREATE TABLE vo (a int PRIMARY KEY, b text);
CREATE TABLE vo_parent (a int) PARTITION BY RANGE (a);
CREATE TABLE vo_child PARTITION OF vo_parent FOR VALUES FROM (0) TO (100);
INSERT INTO vo SELECT g, 'v' || g FROM generate_series(1, 50) g;
VACUUM vo;
VACUUM FULL vo;
VACUUM FREEZE vo;
VACUUM FULL FREEZE ANALYZE vo;
VACUUM FREEZE ANALYSE vo (a);
VACUUM ANALYZE FULL vo;
VACUUM (FREEZE, FULL false, ANALYZE off) vo;
VACUUM (DISABLE_PAGE_SKIPPING) vo;
VACUUM (INDEX_CLEANUP) vo;
VACUUM (INDEX_CLEANUP auto) vo;
VACUUM (INDEX_CLEANUP 'AUTO') vo;
VACUUM (INDEX_CLEANUP on) vo;
VACUUM (INDEX_CLEANUP 0) vo;
VACUUM (INDEX_CLEANUP maybe) vo;
VACUUM (INDEX_CLEANUP 2) vo;
VACUUM (PROCESS_TOAST false) vo;
VACUUM (PROCESS_TOAST false, FULL) vo;
VACUUM (TRUNCATE false) vo;
VACUUM (TRUNCATE) vo;
VACUUM (TRUNCATE auto) vo;
VACUUM (PARALLEL 2) vo;
VACUUM (PARALLEL 0, FULL) vo;
VACUUM (PARALLEL 1, FULL) vo;
VACUUM (PARALLEL) vo;
VACUUM (PARALLEL -1) vo;
VACUUM (PARALLEL 1025) vo;
VACUUM (PARALLEL 1.5) vo;
VACUUM (PARALLEL 'two') vo;
VACUUM (PARALLEL 99999999999) vo;
VACUUM (BUFFER_USAGE_LIMIT '1MB') vo;
VACUUM (BUFFER_USAGE_LIMIT 0, FULL) vo;
VACUUM (BUFFER_USAGE_LIMIT 0, FULL, ANALYZE) vo;
VACUUM (BUFFER_USAGE_LIMIT '1kB') vo;
VACUUM (DISABLE_PAGE_SKIPPING, FULL) vo;
VACUUM (SKIP_DATABASE_STATS) vo;
VACUUM (ONLY_DATABASE_STATS);
VACUUM (ONLY_DATABASE_STATS, VERBOSE false, PROCESS_MAIN false, PROCESS_TOAST false);
VACUUM (ONLY_DATABASE_STATS, INDEX_CLEANUP off, TRUNCATE off, PARALLEL 2);
VACUUM (ONLY_DATABASE_STATS) vo;
VACUUM (ONLY_DATABASE_STATS, FREEZE);
VACUUM (ONLY_DATABASE_STATS, SKIP_LOCKED);
VACUUM (ONLY_DATABASE_STATS false, FREEZE) vo;
VACUUM (FULL, FULL false) vo;
VACUUM (VERBOSE false, SKIP_LOCKED false) vo;
VACUUM (foo) vo;
VACUUM (freeze 2) vo;
VACUUM (full maybe, foo) vo;
VACUUM (foo, full maybe) vo;
VACUUM (select) vo;
VACUUM vo (a);
VACUUM (ANALYZE false) vo (a);
VACUUM (FREEZE) vo (a);
VACUUM (foo) missing_table;
VACUUM (foo) vo extra;
VACUUM (skip_locked) missing_table;
VACUUM PROCESS_MAIN vo;
VACUUM FREEZE FULL vo;
VACUUM ();
-- PROCESS_MAIN false vacuums no table, but still analyzes.
SELECT vacuum_count, analyze_count FROM pg_stat_user_tables WHERE relname = 'vo';
VACUUM (PROCESS_MAIN false) vo;
VACUUM (PROCESS_MAIN false, ANALYZE) vo;
SELECT vacuum_count, analyze_count FROM pg_stat_user_tables WHERE relname = 'vo';
VACUUM (PROCESS_MAIN true) vo;
SELECT vacuum_count FROM pg_stat_user_tables WHERE relname = 'vo';
-- SKIP_LOCKED passes over a table whose lock a prepared transaction holds.
BEGIN;
LOCK TABLE vo IN ACCESS EXCLUSIVE MODE;
LOCK TABLE vo_child IN SHARE UPDATE EXCLUSIVE MODE;
PREPARE TRANSACTION 'vacuum_options_lock';
VACUUM (SKIP_LOCKED) vo;
VACUUM (SKIP_LOCKED, FULL) vo_child, vo;
VACUUM (SKIP_LOCKED) vo_parent;
VACUUM (SKIP_LOCKED, ANALYZE) vo_parent;
VACUUM (SKIP_LOCKED);
COMMIT PREPARED 'vacuum_options_lock';
SELECT relname, vacuum_count FROM pg_stat_user_tables
  WHERE relname IN ('vo', 'vo_child') ORDER BY relname;
DROP TABLE vo, vo_parent;
